alter table public.mn_apps drop constraint mn_apps_category_check;
alter table public.mn_apps add constraint mn_apps_category_check check(category in ('Discover','Artifacts','Make music','Sound toys','Tools'));
update public.mn_apps set status='archived' where id in ('loop-garden','chord-colors','pocket-tempo');
insert into public.mn_apps(id,creator,name,description,about,url,screenshot,category,kind,status,price,account_required,permissions,embed_mode) values('medellin-metal','musicnerd','Medellín Metal','A listening history of Medellín’s metal scene and its connections to the world.','Explore the bands, records, people, and places behind Medellín’s metal scene through an interactive story, listening room, timeline, and source archive. Available in English and Spanish. Archive photography: Román González / Universo Centro.','https://medellinmetal-mn.vercel.app/','https://medellinmetal-mn.vercel.app/assets/parabellum-archive.jpg','Artifacts','external','published','Free',false,'{}','embedded');
